// Badge: a count or a short label set off by a fill (shadcn/ui's, generated by its CLI and ours from
// then on). Its look is the Tailwind classes below on shadcn's tokens, which tailwind.css takes from
// frost; a destructive fill carries frost's --on-ink as its text.

import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from 'cn';
import { Slot } from 'radix-ui';
import type { ComponentProps } from 'react';

const badgeVariants = cva(
  'inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-full border border-transparent px-2 py-0.5 text-xs font-medium whitespace-nowrap transition-[color,box-shadow] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-3',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground [a&]:hover:bg-primary/90',
        secondary: 'bg-secondary text-secondary-foreground [a&]:hover:bg-secondary/90',
        destructive: 'bg-destructive text-on-ink focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 [a&]:hover:bg-destructive/90',
        outline: 'border-border text-foreground [a&]:hover:bg-accent [a&]:hover:text-accent-foreground',
        ghost: '[a&]:hover:bg-accent [a&]:hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 [a&]:hover:underline',
        // a count beside a button or tab label; the caller tints it (`bg-waiting`, `bg-error`)
        count: 'rounded-[3px] bg-planned px-1.5 py-0 text-[11.5px] leading-[inherit] font-bold text-on-ink',
        // a card's label (category, sub-category, complexity); a dashed purple edge while Seismic suggested it
        label: 'gap-[3px] border-line bg-chip px-[5px] py-0 text-[.92em] leading-[15px] font-medium tracking-[.01em] text-muted-foreground normal-case [&>svg]:size-auto! data-[suggested=true]:border-dashed data-[suggested=true]:border-proposal',
        // the pill of a card a text links to (a link, or a span once the card is gone), also built as raw DOM in the composer: see `pillClass`
        pill: 'max-w-full gap-1.5 overflow-visible border-glass-edge bg-chip py-px pr-2 pl-[7px] align-baseline text-[.92em] leading-[1.45] font-normal text-working no-underline focus-visible:border-working focus-visible:ring-0 [a&]:hover:border-working [a&]:hover:bg-[color-mix(in_srgb,var(--working)_8%,var(--chip))]',
        // a chip: a tag or label that may carry a remove button after its text
        chip: 'h-6 gap-1 bg-chip py-0 pr-[3px] pl-2.5 text-[12.5px] leading-none font-normal',
        // the pin at a card's corner: a count or mark on a glossy dot in the colour of --pin, which the
        // card's state sets; counter-scaled so it stays readable when the canvas is zoomed out
        pin: 'absolute isolate top-[-10px] right-[-8px] grid h-6 min-w-6 origin-[70%_30%] scale-[max(1,calc(.9/var(--s)))] place-items-center overflow-visible rounded-xl px-[7px] text-[13px] leading-none font-bold text-on-ink [--pin:var(--waiting)] before:absolute before:inset-0 before:-z-10 before:rounded-[inherit] before:[background:radial-gradient(circle_at_35%_30%,rgba(255,255,255,.45),transparent_45%),var(--pin)] before:shadow-[0_0_0_2px_var(--glass-edge),0_4px_10px_-2px_rgba(0,0,0,.25)] before:content-[\'\']',
      },
    },
    defaultVariants: { variant: 'default' },
  },
);

/** `pulse` sends a sonar ring outward from a pin, for what waits for the owner. */
function Badge({ className, variant = 'default', asChild = false, pulse, ...props }: ComponentProps<'span'> & VariantProps<typeof badgeVariants> & { asChild?: boolean; pulse?: boolean }) {
  const Comp = asChild ? Slot.Root : 'span';
  return <Comp data-slot="badge" data-variant={variant} className={cn(badgeVariants({ variant }), pulse && 'after:pointer-events-none after:absolute after:-inset-0.5 after:-z-20 after:animate-[pulse_1.8s_ease-out_infinite] after:rounded-[inherit] after:border-2 after:border-[var(--pin)] after:opacity-0 after:content-[\'\']', className)} {...props} />;
}

/** The class string of a badge variant for what is not React (the card-link pill the composer builds as DOM); `extra` joins it. */
const badgeClass = (variant: NonNullable<VariantProps<typeof badgeVariants>['variant']>, ...extra: string[]) => cn(badgeVariants({ variant }), ...extra);

export { Badge, badgeClass, badgeVariants };
